package cloud.kosch.kandroid.bridge;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.widget.*;import java.util.*;
public class NewsWidgetProvider extends AppWidgetProvider {static int[] ids={R.id.n1,R.id.n2,R.id.n3,R.id.n4,R.id.n5,R.id.n6};@Override public void onUpdate(Context c,AppWidgetManager m,int[] w){for(int id:w)update(c,m,id);} @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if("cloud.kosch.kandroid.bridge.REFRESH_NEWS".equals(i.getAction())){AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,NewsWidgetProvider.class)))update(c,m,id);}}
 static void update(Context c,AppWidgetManager m,int wid){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_news);r.setTextViewText(R.id.header,"AI NEWS · LIVE");Intent ri=new Intent("cloud.kosch.kandroid.bridge.REFRESH_NEWS").setPackage(c.getPackageName());r.setOnClickPendingIntent(R.id.refresh,PendingIntent.getBroadcast(c,wid,ri,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));m.updateAppWidget(wid,r);new Thread(()->{try{List<NewsRepository.Item> n=NewsRepository.fetch(1);for(int i=0;i<ids.length;i++){if(i<n.size()){NewsRepository.Item x=n.get(i);r.setTextViewText(ids[i],NewsRepository.pretty(x));Intent o=new Intent(Intent.ACTION_VIEW,Uri.parse(x.url));r.setOnClickPendingIntent(ids[i],PendingIntent.getActivity(c,1000+wid*10+i,o,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));}else r.setTextViewText(ids[i],"");}r.setTextViewText(R.id.footer,"Live · "+new java.text.SimpleDateFormat("HH:mm",java.util.Locale.GERMANY).format(new java.util.Date()));m.updateAppWidget(wid,r);}catch(Exception e){r.setTextViewText(R.id.footer,"Offline · tippe ↻");m.updateAppWidget(wid,r);}}).start();}}
